<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { Download, X, ArrowUpRight } from 'lucide-vue-next'
import * as XLSX from 'xlsx'
import { catalog } from '../prototype-store'
import { observations, regions, filterObservations } from '../domain'
import { capabilityFor, modeLabels, saveCapability, type Capability } from '../capabilities'
import { analyzeBenefits, riskLabels, type Risk } from '../analytics'
const props=defineProps<{mode:'risks'|'coverage'}>(),route=useRoute(),router=useRouter()
const from=ref('2026-08-01'),to=ref('2026-10-29'),region=ref(''),threshold=ref(70),kind=ref(''),sourceFilter=ref(''),search=ref(''),idFilter=ref(Number(route.query.benefit)||0),page=ref(1),selected=ref<Risk|null>(null)
watch(()=>route.query.benefit,v=>{idFilter.value=Number(v)||0})
function selectCoverage(value:string){sourceFilter.value=value;if(props.mode==='risks')router.push({path:'/apps/social-benefits/coverage',query:{filter:value}})}
watch(()=>route.query.filter,v=>{sourceFilter.value=typeof v==='string'?v:''},{immediate:true})
const limit=computed(()=>Math.max(1,Math.min(100,Number(threshold.value)||70)))
const entries=computed(()=>catalog.map(b=>({...b,capability:capabilityFor(b.id)})))
const coverageStats=computed(()=>({total:entries.value.length,auto:entries.value.filter(b=>b.capability.eligibility==='auto'&&b.capability.usage==='auto').length,noSource:entries.value.filter(b=>b.capability.eligibility==='none'||b.capability.usage==='none').length,eligibilityMissing:entries.value.filter(b=>b.capability.eligibility==='none').length,usageMissing:entries.value.filter(b=>b.capability.usage==='none').length,manual:entries.value.filter(b=>b.capability.eligibility==='manual'||b.capability.usage==='manual').length}))
const data=computed(()=>filterObservations(observations,{from:from.value,to:to.value,region:region.value,category:'',benefitId:0,status:'',search:'',gender:'',registry:''}))
const risks=computed(()=>analyzeBenefits(catalog,data.value,limit.value))
const riskRows=computed(()=>risks.value.filter(r=>(!kind.value||r.kind===kind.value)&&`${r.benefitId} ${r.title} ${r.evidence}`.toLowerCase().includes(search.value.toLowerCase())))
const coverageRows=computed(()=>entries.value.filter(b=>(!idFilter.value||b.id===idFilter.value)&&`${b.id} ${b.name}`.toLowerCase().includes(search.value.toLowerCase())&&(!sourceFilter.value||sourceFilter.value==='missing'&&(b.capability.eligibility==='none'||b.capability.usage==='none')||sourceFilter.value==='eligibility'&&b.capability.eligibility==='none'||sourceFilter.value==='usage'&&b.capability.usage==='none'||sourceFilter.value==='auto'&&b.capability.eligibility==='auto'&&b.capability.usage==='auto'||sourceFilter.value==='manual'&&(b.capability.eligibility==='manual'||b.capability.usage==='manual'))))
watch([kind,sourceFilter,search,idFilter,from,to,region,threshold],()=>page.value=1)
const editing=ref(0),draft=ref<Capability>({...capabilityFor(1)}),message=ref(''),editError=ref('')
function editCapability(id:number){editing.value=id;draft.value={...capabilityFor(id)};editError.value=''}
function save(){try{saveCapability(editing.value,draft.value);message.value='Tekshirish imkoniyatlari saqlandi. Tahliliy natijalar qayta hisoblandi.';editing.value=0}catch(e){editError.value=(e as Error).message}}
interface Proposal {action:string;reason:string;owner:string;state:string}
const proposals=ref<Record<string,Proposal>>({}),proposal=ref<Proposal>({action:'',reason:'',owner:'',state:'O‘rganilmoqda'})
try{const stored=JSON.parse(localStorage.getItem('sb-risk-proposals-v1')??'{}');for(const[k,v]of Object.entries(stored))if(v&&typeof v==='object'&&['action','reason','owner','state'].every(f=>typeof (v as Record<string,unknown>)[f]==='string'))proposals.value[k]=v as Proposal}catch{}
watch(()=>props.mode,()=>{selected.value=null;editing.value=0;page.value=1;kind.value=''})
const proposalError=ref('')
function open(r:Risk){selected.value=r;proposalError.value='';proposal.value={...(proposals.value[r.id]??{action:'Sababini o‘rganish',reason:'',owner:'',state:'O‘rganilmoqda'})}}
function saveProposal(){if(!selected.value)return;if(!proposal.value.reason.trim()||!proposal.value.owner.trim()){proposalError.value='Asos va mas’ulni kiriting.';return}try{const next={...proposals.value,[selected.value.id]:{...proposal.value}};localStorage.setItem('sb-risk-proposals-v1',JSON.stringify(next));proposals.value=next;proposalError.value='';message.value='Ko‘rib chiqish taklifi saqlandi. Bu amal imtiyozni bekor qilmaydi.';selected.value=null}catch{proposalError.value='Brauzer xotirasiga saqlab bo‘lmadi.'}}
function exportData(){const rows=props.mode==='coverage'?coverageRows.value.map(b=>({Raqam:b.id,Nomi:b.name,Moslik:modeLabels[b.capability.eligibility],'Moslik manbasi':b.capability.eligibilitySource,Foydalanish:modeLabels[b.capability.usage],'Foydalanish manbasi':b.capability.usageSource,Sabab:b.capability.reason,Masul:b.capability.owner,Reja:b.capability.plan})):riskRows.value.map(r=>({Risk:riskLabels[r.kind],Imtiyoz:r.benefitId||'',Nomi:r.title,Daraja:r.severity,Shaxslar:r.people,'Ma’lum summa':r.amount,Dalil:r.evidence,'Tahlil chegarasi':r.limits,Taklif:r.proposal,'Ko‘rib chiqish holati':proposals.value[r.id]?.state??'Yangi'}));const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows),'Natijalar');XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet([{Izoh:'NAMUNAVIY ANALITIKA — avtomatik yakuniy qaror emas',from:from.value,to:to.value,Hudud:region.value||'Barchasi',Risk:kind.value,Manba:sourceFilter.value,Qidiruv:search.value,Imtiyoz:idFilter.value||'Barchasi','Past foydalanish chegarasi':threshold.value}]),'Filtrlar');XLSX.writeFile(book,props.mode==='coverage'?'Imtiyozlar_tekshiruv_qamrovi.xlsx':'Imtiyozlar_risk_tahlili.xlsx')}
function usageLink(r:Risk){return {path:'/apps/social-benefits/usage',query:{category:r.category??'',benefit:String(r.benefitId),status:r.kind==='mismatch'?'mismatch':r.kind==='lowUsage'?'unused':'',from:from.value,to:to.value,region:region.value}}}
</script>
<template>

<div class="an-stats"><button @click="sourceFilter='';kind='';idFilter=0;search='' "><span>Jami imtiyozlar</span><b>{{ coverageStats.total }}</b></button><button class="metric-good" @click="selectCoverage('auto')"><span>Ikkala tekshiruv avtomatik</span><b>{{ coverageStats.auto }}</b></button><button :class="coverageStats.noSource>0?'metric-warning':'metric-good'" @click="sourceFilter='missing';kind='source'"><span>Kamida bitta manba yo‘q</span><b>{{ coverageStats.noSource }} / {{ coverageStats.total }}</b></button><button :class="coverageStats.manual>0?'metric-warning':'metric-neutral'" @click="selectCoverage('manual')"><span>Qo‘lda ko‘rib chiqiladigan</span><b>{{ coverageStats.manual }}</b></button></div>
<div class="an-tabs"><RouterLink to="/apps/social-benefits/risks" :class="{active:mode==='risks'}">Risklar</RouterLink><RouterLink to="/apps/social-benefits/coverage" :class="{active:mode==='coverage'}">Tekshirish imkoniyatlari</RouterLink></div>
<section class="an-panel"><div class="an-toolbar"><input v-model="search" aria-label="Analitik jadvaldan qidirish" placeholder="Imtiyoz raqami, nomi yoki dalil" /><template v-if="mode==='risks'"><label>Davr boshi<input v-model="from" type="date" /></label><label>Davr oxiri<input v-model="to" type="date" /></label><select v-model="region" aria-label="Risk hududi"><option value="">Barcha hududlar</option><option v-for="r in regions" :key="r">{{ r }}</option></select><label>Past foydalanish chegarasi, %<input v-model.number="threshold" type="number" min="1" max="100" /></label></template><select v-else v-model="sourceFilter" aria-label="Manba mavjudligi filtri"><option value="">Barcha imtiyozlar</option><option value="missing">Kamida bitta manba yo‘q</option><option value="eligibility">Moslik manbasi yo‘q</option><option value="usage">Foydalanish manbasi yo‘q</option><option value="auto">Ikkala tekshiruv avtomatik</option><option value="manual">Qo‘lda ko‘rib chiqiladigan</option></select><button @click="exportData"><Download :size="15" /> Excel</button><button @click="search='';kind='';sourceFilter='';idFilter=0;page=1">Filtrlarni tozalash</button></div><p v-if="idFilter&&mode==='coverage'">Imtiyoz №{{ idFilter }} ko‘rsatilmoqda.</p><p v-if="from>to&&mode==='risks'" role="alert" class="an-error">Davr sanalarini tekshiring.</p><p v-if="message" role="status" class="an-success">{{ message }}</p>
<template v-if="mode==='coverage'"><details class="an-note"><summary>Hisoblash tartibi</summary><div>Moslik manbasi yo‘q: <b>{{ coverageStats.eligibilityMissing }}</b> ta · Foydalanish manbasi yo‘q: <b>{{ coverageStats.usageMissing }}</b> ta. Bir imtiyoz ikkala guruhda bo‘lishi mumkin; yuqoridagi “kamida bitta manba yo‘q” sonida bir marta hisoblanadi. </div></details><div class="an-table"><table><thead><tr><th>Imtiyoz</th><th>Moslik tekshiruvi</th><th>Foydalanish tekshiruvi</th><th>Cheklov / mas’ul</th><th></th></tr></thead><tbody><tr v-for="b in coverageRows.slice((page-1)*15,page*15)" :key="b.id"><td class="an-name"><small>№{{ b.id }}</small><b>{{ b.name }}</b></td><td><span :class="['an-tag',b.capability.eligibility]">{{ modeLabels[b.capability.eligibility] }}</span><p>{{ b.capability.eligibilitySource||'Manba belgilanmagan' }}</p></td><td><span :class="['an-tag',b.capability.usage]">{{ modeLabels[b.capability.usage] }}</span><p>{{ b.capability.usageSource||'Manba belgilanmagan' }}</p></td><td><p>{{ b.capability.reason }}</p><small>{{ b.capability.owner||'Mas’ul belgilanmagan' }}</small></td><td><button @click="editCapability(b.id)">Sozlash</button></td></tr><tr v-if="!coverageRows.length"><td colspan="5">Mos imtiyoz topilmadi.</td></tr></tbody></table></div></template>
<template v-else><div class="an-risk-types"><button :class="{active:!kind}" @click="kind=''">Barchasi <b>{{ risks.length }}</b></button><button v-for="(label,key) in riskLabels" :key="key" :class="[key,{active:kind===key}]" @click="kind=key"><span>{{ label }}</span><b>{{ risks.filter(r=>r.kind===key).length }}</b></button></div><details class="an-note"><summary>Hisoblash tartibi</summary><div>Past foydalanish signali: kamida 5 ta huquqi bor baholash yozuvi va foydalanish ulushi {{ limit }}% dan past. Taqsimot signali: ma’lum summa / qamrab olingan shaxs tanlangan qamrov o‘rtachasidan kamida 1,25 baravar. Bu mezonlar prototip tahlili uchun; yakuniy siyosiy yoki huquqiy xulosa emas. Manbasi yo‘q choralar past foydalanish yoki nomuvofiqlik hisobiga kiritilmaydi.</div></details><div class="an-table"><table><thead><tr><th>Risk / imtiyoz</th><th>Dalil va ta’sir</th><th>Daraja</th><th>Ko‘rib chiqish</th><th></th></tr></thead><tbody><tr v-for="r in riskRows.slice((page-1)*15,page*15)" :key="r.id" :class="r.kind==='mismatch'||r.kind==='lowUsage'?'an-risk-row':'an-warning-row'"><td class="an-name"><span :class="['an-type',r.kind==='mismatch'||r.kind==='lowUsage'?'danger':'manual']">{{ riskLabels[r.kind] }}</span><b>{{ r.benefitId?'№'+r.benefitId+' · ':'' }}{{ r.title }}</b></td><td><p>{{ r.evidence }}</p><small>{{ r.people }} ta qamrab olingan shaxs · {{ r.amount===null?'Moliyaviy ta’sir aniqlanmagan':r.amount.toLocaleString('uz-UZ')+' so‘m ma’lum summa' }}</small></td><td><span :class="['an-tag',r.kind==='mismatch'||r.kind==='lowUsage'?'danger':'manual']">{{ r.severity }}</span></td><td>{{ proposals[r.id]?.state??'Yangi' }}</td><td><button @click="open(r)">Dalil va taklif</button></td></tr><tr v-if="!riskRows.length"><td colspan="5">Tanlangan mezon va davr bo‘yicha signal topilmadi. Bu risk umuman yo‘q degani emas.</td></tr></tbody></table></div></template>
<div class="an-pagination"><span>{{ mode==='coverage'?coverageRows.length:riskRows.length }} ta natija · {{ page }} / {{ Math.max(1,Math.ceil((mode==='coverage'?coverageRows.length:riskRows.length)/15)) }}</span><button :disabled="page===1" @click="page--">Oldingi</button><button :disabled="page*15>=(mode==='coverage'?coverageRows.length:riskRows.length)" @click="page++">Keyingi</button></div></section>
<div v-if="editing" class="an-overlay" @click.self="editing=0" @keydown.esc="editing=0"><section class="an-dialog" role="dialog" aria-modal="true" aria-labelledby="coverage-title"><header><h2 id="coverage-title">№{{ editing }} · Tekshirish imkoniyatlari</h2><button @click="editing=0" aria-label="Sozlamani yopish"><X :size="18" /></button></header><p>{{ catalog.find(b=>b.id===editing)?.name }}</p><form @submit.prevent="save"><label>Moslikni tekshirish<select v-model="draft.eligibility" aria-label="Moslikni tekshirish usuli"><option v-for="(label,key) in modeLabels" :key="key" :value="key">{{ label }}</option></select></label><label>Moslik manbasi<input v-model="draft.eligibilitySource" :required="draft.eligibility==='auto'" /></label><label>Foydalanishni tekshirish<select v-model="draft.usage" aria-label="Foydalanishni tekshirish usuli"><option v-for="(label,key) in modeLabels" :key="key" :value="key">{{ label }}</option></select></label><label>Foydalanish manbasi<input v-model="draft.usageSource" :required="draft.usage==='auto'" /></label><label>Cheklov yoki manba holati sababi<textarea v-model="draft.reason" required rows="3" /></label><label>Mas’ul tashkilot<input v-model="draft.owner" required /></label><label>Manba olish yoki tekshiruvni tashkil etish rejasi<textarea v-model="draft.plan" rows="3" /></label><p v-if="editError" role="alert" class="an-error">{{ editError }}</p><button class="an-primary" type="submit">Tekshiruv sozlamalarini saqlash</button></form></section></div>
<div v-if="selected" class="an-overlay" @click.self="selected=null" @keydown.esc="selected=null"><section class="an-dialog" role="dialog" aria-modal="true" aria-labelledby="risk-title"><header><h2 id="risk-title">{{ riskLabels[selected.kind] }}</h2><button @click="selected=null" aria-label="Risk kartasini yopish"><X :size="18" /></button></header><h3>{{ selected.title }}</h3><div class="an-block"><small>DALIL</small><p>{{ selected.evidence }}</p></div><details class="an-block"><summary>Dalil cheklovlari</summary><p>{{ selected.limits }}</p></details><div class="an-block"><small>KO‘RIB CHIQILADIGAN TAKLIF</small><p>{{ selected.proposal }}</p></div><RouterLink v-if="selected.kind!=='source'" :to="usageLink(selected)" class="an-link">Tegishli yozuvlarni ochish <ArrowUpRight :size="15" /></RouterLink><RouterLink v-else :to="{path:'/apps/social-benefits/coverage',query:{benefit:selected.benefitId}}" class="an-link">Imtiyoz manbalarini ko‘rish <ArrowUpRight :size="15" /></RouterLink><h3>Ko‘rib chiqish taklifini shakllantirish</h3><form @submit.prevent="saveProposal"><label>Taklif turi<select v-model="proposal.action"><option>Sababini o‘rganish</option><option>Mezonlarni o‘zgartirish</option><option>Imtiyozlarni birlashtirishni ko‘rib chiqish</option><option>Yangi imtiyoz yaratish</option><option>Qayta taqsimlash</option><option>Tugatishga ko‘rib chiqish</option><option>Manba ma’lumotini to‘ldirish</option></select></label><label>Taklif asosi va tekshiriladigan dalillar<textarea v-model="proposal.reason" required rows="4" /></label><label>Mas’ul<input v-model="proposal.owner" required /></label><label>Ko‘rib chiqish holati<select v-model="proposal.state"><option>O‘rganilmoqda</option><option>Taklif tayyorlanmoqda</option><option>Ko‘rib chiqishga kiritilgan</option><option>Qo‘shimcha dalil kerak</option></select></label><p v-if="proposalError" role="alert" class="an-error">{{ proposalError }}</p><button class="an-primary">Taklifni saqlash</button></form></section></div>
</template>
<style scoped src="./benefits-analytics.css"></style>
